# General Studies (Part B), Indian Polity and Economy: the country's political system, rural
# development, planning and economic reforms (the syllabus wording). Articles as in the
# Constitution of India; no office-holders, budgets or figures that change.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Fundamental Rights", "Which Article of the Constitution abolishes titles, other than military and academic distinctions?",
      ["Article 18", "Article 17", "Article 15", "Article 21"],
      "Article 18 abolishes titles and bars citizens from accepting titles from a foreign state. Article 17 abolishes untouchability."),
    S(1, 2, "Fundamental Duties", "How many Fundamental Duties does the Constitution list in Article 51A today?",
      ["11", "10", "12", "9"],
      "The 42nd Amendment (1976) added ten duties, and the 86th Amendment (2002) added the eleventh: a parent's duty to give a child aged 6 to 14 the chance of education."),
    S(1, 1, "State executive", "Which Article of the Constitution says there shall be a Governor for each state?",
      ["Article 153", "Article 155", "Article 163", "Article 168"],
      "Article 153 provides a Governor for each state. Article 155 covers the appointment, Article 163 the Council of Ministers and Article 168 the state Legislature."),
    S(1, 1, "Local government", "Which Constitutional amendment gave constitutional status to Panchayati Raj institutions?",
      ["The 73rd Amendment", "The 74th Amendment", "The 42nd Amendment", "The 61st Amendment"],
      "The 73rd Amendment (1992) added Part IX on panchayats. The 74th did the same for municipalities, and the 61st lowered the voting age to 18."),
    S(1, 2, "Parliament", "Under Article 85, what is the longest gap allowed between two sessions of Parliament?",
      ["Six months", "Three months", "Four months", "One year"],
      "Article 85 says six months shall not pass between the last sitting of one session and the first sitting of the next, so Parliament meets at least twice a year."),
    S(1, 1, "Planning", "Which body replaced the Planning Commission in 2015?",
      ["NITI Aayog", "Finance Commission", "National Development Council", "Inter-State Council"],
      "NITI Aayog (National Institution for Transforming India) replaced the Planning Commission on 1 January 2015."),
    S(1, 2, "Parliament", "Under which Article can the President summon a joint sitting of both Houses of Parliament?",
      ["Article 108", "Article 110", "Article 123", "Article 352"],
      "Article 108 provides for a joint sitting when the Houses disagree on an ordinary Bill. Article 110 defines Money Bills and Article 123 covers ordinances."),
    S(1, 2, "Rural development", "How many days of wage employment a year does the MGNREGA guarantee to every rural household that asks for work?",
      ["100 days", "150 days", "120 days", "90 days"],
      "The Mahatma Gandhi National Rural Employment Guarantee Act, 2005 guarantees at least 100 days of unskilled manual work a year to each rural household that wants it."),
    S(1, 1, "Fundamental Rights", "Which Article gives the right to move the Supreme Court for the enforcement of Fundamental Rights?",
      ["Article 32", "Article 226", "Article 19", "Article 44"],
      "Article 32, the Right to Constitutional Remedies, lets a person go straight to the Supreme Court. Article 226 gives High Courts a similar but wider power."),
    S(1, 2, "Economic reforms", "The economic reforms begun in India in 1991 are often summed up as LPG. What does it stand for?",
      ["Liberalisation, privatisation, globalisation", "Licensing, planning, growth", "Land, poverty and growth", "Labour, production, goods"],
      "The 1991 reforms freed industry from licensing (liberalisation), opened public sector firms to private ownership (privatisation) and opened the economy to world trade and investment (globalisation)."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Constitution", "Which Part of the Constitution contains the Directive Principles of State Policy?",
      ["Part IV", "Part III", "Part IV-A", "Part V"],
      "The Directive Principles are in Part IV (Articles 36 to 51). Part III holds the Fundamental Rights and Part IV-A the Fundamental Duties."),
    S(2, 2, "Union executive", "Who elects the Vice-President of India?",
      ["Members of both Houses of Parliament", "MPs and members of state Assemblies", "The people directly", "The Rajya Sabha alone"],
      "Under Article 66 the Vice-President is elected by an electoral college of the members of both Houses of Parliament. State legislators vote only in the President's election."),
    S(2, 2, "Fundamental Rights", "Which Article makes free and compulsory education for children aged 6 to 14 a Fundamental Right?",
      ["Article 21A", "Article 45", "Article 24", "Article 29"],
      "Article 21A was added by the 86th Amendment (2002). Article 45 now asks the state to provide early childhood care for children under six, and Article 24 bans child labour in factories."),
    S(2, 1, "Constitution", "Which Schedule of the Constitution lists the official languages of India?",
      ["The Eighth Schedule", "The Seventh Schedule", "The Tenth Schedule", "The Sixth Schedule"],
      "The Eighth Schedule lists the 22 languages. The Seventh has the Union, State and Concurrent lists, and the Tenth deals with defection."),
    S(2, 1, "Parliament", "In which House can a Money Bill be introduced?",
      ["Only in the Lok Sabha", "Only in the Rajya Sabha", "In either House", "Only at a joint sitting"],
      "Article 109 says a Money Bill can be introduced only in the Lok Sabha, and the Rajya Sabha can only recommend changes within 14 days."),
    S(2, 2, "Banking", "In which year was the Reserve Bank of India set up?",
      ["1935", "1947", "1949", "1969"],
      "The RBI began work on 1 April 1935 under the RBI Act, 1934, and was nationalised in 1949. Fourteen large banks were nationalised in 1969."),
    S(2, 2, "Economy", "What does a country's Gross Domestic Product (GDP) measure?",
      ["Final goods and services produced in it", "Its exports minus its imports", "Total taxes collected by government", "Money held in its banks"],
      "GDP is the market value of all final goods and services produced within a country's borders in a year. Exports minus imports is the trade balance."),
    S(2, 1, "Constitution", "Who was elected President of the Constituent Assembly?",
      ["Rajendra Prasad", "B. R. Ambedkar", "Jawaharlal Nehru", "B. N. Rau"],
      "Dr Rajendra Prasad was the permanent President of the Constituent Assembly. Dr B. R. Ambedkar chaired its Drafting Committee."),
    S(2, 2, "Agriculture", "The Green Revolution of the 1960s first raised the output of which crops most?",
      ["Wheat and rice", "Pulses and oilseeds", "Cotton and jute", "Tea and coffee"],
      "High-yielding seeds, irrigation and fertilisers raised wheat and then rice output, mainly in Punjab, Haryana and western Uttar Pradesh. Pulses gained little."),
    S(2, 2, "Planning", "Which sector did India's First Five-Year Plan (1951-56) give the highest priority?",
      ["Agriculture and irrigation", "Heavy industry", "Defence production", "Information technology"],
      "The First Plan focused on agriculture and irrigation to tackle food shortages. The Second Plan (Mahalanobis model) shifted priority to heavy industry."),

    # ---------- Drill only ----------
    S(0, 1, "Union executive", "Under Article 75, to which body is the Council of Ministers collectively responsible?",
      ["The Lok Sabha", "The President", "The Rajya Sabha", "The Supreme Court"],
      "Article 75(3) makes the Council of Ministers collectively responsible to the House of the People, the Lok Sabha, which can remove it by a vote of no confidence."),
    S(0, 2, "Constitution", "Which amendment is often called the \"mini-Constitution\" for the number of changes it made?",
      ["The 42nd Amendment", "The 44th Amendment", "The 1st Amendment", "The 52nd Amendment"],
      "The 42nd Amendment (1976) changed many parts of the Constitution, adding \"socialist\", \"secular\" and \"integrity\" to the Preamble and the Fundamental Duties."),
    S(0, 2, "Banking", "What is the repo rate?",
      ["The rate at which RBI lends to banks", "The rate banks pay on savings", "The rate banks charge farmers", "The rate of tax on interest"],
      "The repo rate is the interest the Reserve Bank charges when it lends short-term money to commercial banks against securities. Raising it makes borrowing dearer."),
    S(0, 2, "Emergency", "Under which Article can the President proclaim a national emergency?",
      ["Article 352", "Article 356", "Article 360", "Article 370"],
      "Article 352 covers war, external aggression or armed rebellion. Article 356 is President's Rule in a state and Article 360 a financial emergency."),
]
